-- El historial de gestión no se edita ni se borra: lo garantiza la base, no solo la aplicación (misma función que el historial de stock).
CREATE TRIGGER "inquiry_events_inmutable" BEFORE UPDATE OR DELETE ON "inquiry_events" FOR EACH ROW EXECUTE FUNCTION "historial_inmutable"();
--> statement-breakpoint
-- Un vínculo consulta–venta no se borra ni se reescribe: lo único permitido es cerrarlo una vez (active true -> false) cuando la venta se anula.
CREATE FUNCTION "vinculo_solo_se_cierra"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'El vínculo entre una consulta y su venta no se borra.' USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  IF OLD.active IS NOT TRUE OR NEW.active IS NOT FALSE OR NEW.ended_at IS NULL
     OR (to_jsonb(NEW) - 'active' - 'ended_at' - 'ended_reason') <> (to_jsonb(OLD) - 'active' - 'ended_at' - 'ended_reason') THEN
    RAISE EXCEPTION 'El vínculo entre una consulta y su venta solo se puede cerrar una vez.' USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  RETURN NEW;
END
$$;
--> statement-breakpoint
CREATE TRIGGER "inquiry_sales_solo_cierre" BEFORE UPDATE OR DELETE ON "inquiry_sales" FOR EACH ROW EXECUTE FUNCTION "vinculo_solo_se_cierra"();
